content.text:
{
  "name": "仪器服务器客户端",
  "name_en": "Instrument Server Client",
  "manufacturer": "",
  "description": "用于连接实验室仪器管理服务器的客户端组件，可与服务器建立连接、发送请求并断开连接，适合远程仪器访问与实验自动化控制场景。",
  "description_en": "A client component for connecting to a laboratory instrument management server. It can establish a connection, send requests, and disconnect, supporting remote instrument access and lab automation workflows.",
  "tag_hints": [
    "instrument server",
    "remote instrument control",
    "lab automation",
    "client-server communication",
    "networked instruments"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到仪器管理服务器。",
      "description_en": "Connect to the instrument management server."
    },
    {
      "action_name": "auto-ask",
      "description": "向服务器发送请求并获取响应。",
      "description_en": "Send a request to the server and receive a response."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与仪器管理服务器的连接。",
      "description_en": "Disconnect from the instrument management server."
    }
  ]
}

